INSERT INTO contrato_pagamento_opcao (id,nome,descricao1,descricaon,recebe_valor,recebe_data,recebe_evento,recebe_indexador,data_criacao,criacao_user_id,data_modificacao,modificacao_user_id) VALUES (1,'Honorários iniciais','[opcao_pagamento]: O valor de R$ [valor] ([valor_extenso]). O pagamento será parcelado em  [numero_parcelas] ([numero_parcelas_extenso]) vezes, iniciando-se em [data] e as demais parcelas no mesmo dia dos meses subsequentes, através de transferência bancária ou PIX.','[opcao_pagamento]: O valor de R$ [valor] ([valor_extenso]). O pagamento será parcelado em  [numero_parcelas] ([numero_parcelas_extenso]) vezes, iniciando-se em [data] e as demais parcelas no mesmo dia dos meses subsequentes, através de transferência bancária ou PIX.','S','S','N','N',null,null,null,null); 
INSERT INTO contrato_pagamento_opcao (id,nome,descricao1,descricaon,recebe_valor,recebe_data,recebe_evento,recebe_indexador,data_criacao,criacao_user_id,data_modificacao,modificacao_user_id) VALUES (2,'Honorários intermediários','[opcao_pagamento]: Serão devidos [numero_indexador][unidade_indexador] ([numero_indexador_extenso] [unidade_indexador_extenso]) [indexador], na condição "ad êxito", a serem pagos após a efetiva implantação de cada [evento]. O pagamento poderá ser parcelado em até [numero_parcelas] ([numero_parcelas_extenso]) vezes, com vencimento na data de recebimento de cada benefício, mediante transferência bancária.','[opcao_pagamento]: Serão devidos [numero_indexador][unidade_indexador] ([numero_indexador_extenso] [unidade_indexador_extenso]) [indexador], na condição "ad êxito", a serem pagos após a efetiva implantação de cada [evento]. O pagamento poderá ser parcelado em até [numero_parcelas] ([numero_parcelas_extenso]) vezes, com vencimento na data de recebimento de cada benefício, mediante transferência bancária.','N','N','S','S',null,null,null,null); 
INSERT INTO contrato_pagamento_opcao (id,nome,descricao1,descricaon,recebe_valor,recebe_data,recebe_evento,recebe_indexador,data_criacao,criacao_user_id,data_modificacao,modificacao_user_id) VALUES (3,'Honorários finais','[opcao_pagamento]: A contratada terá direito a [numero_indexador][unidade_indexador] ([numero_indexador_extenso] [unidade_indexador_extenso]), na condição "ad êxito", sobre o [indexador] obtido, incluindo parcelas vencidas recuperadas por meio de recursos administrativos ou processos judiciais. O pagamento será devido na data de recebimento, mediante a transferência bancária.','[opcao_pagamento]: A contratada terá direito a [numero_indexador][unidade_indexador] ([numero_indexador_extenso] [unidade_indexador_extenso]), na condição "ad êxito", sobre o [indexador] obtido, incluindo parcelas vencidas recuperadas por meio de recursos administrativos ou processos judiciais. O pagamento será devido na data de recebimento, mediante a transferência bancária.','N','N','N','S',null,null,null,null); 
