INSERT INTO template_escritorio (id,escritorio_id,chave,descricao,habilitado,template,titulo,tipo_template,readonly,data_criacao,criacao_user_id,data_modificacao,modificacao_user_id) VALUES (1,1,'EMAIL_CONFIRMACAO_AGENDAMENTO','Confirmação de agendamento','T','<p>Olá <b>{$cliente}</b>,</p><p>Temos agendado com você em: {$data_inicial}, com<span style="color: var(--text-color); font-family: var(--font-family); font-size: var(--font-size);"> {$profissional}.</span></p><p style="line-height: 1;"><br></p><p style="line-height: 1;">Você deseja:</p><p style="line-height: 1;"><a style="border: 1px solid grey; border-radius: 4px; padding: 10px 15px; background-color: #4caf50; color: white;" href="{$link_confirmacao}" target="_blank">Confirmar agendamento</a> <a style="border: 1px solid grey; border-radius: 4px; padding: 10px 15px; background-color: #f44336; color: white;" href="{$link_cancelamento}" target="_blank">Cancelar agendamento</a><br></p><p style="line-height: 1;"><br></p><p style="line-height: 1;"><span style="font-size: 11px; font-family: Arial;">{$escritorio} - </span><span style="color: var(--text-color); font-family: Arial; font-size: 11px;">{$email_escritorio} - </span><span style="font-family: Arial; font-size: 11px; color: var(--text-color);">{$telefone_escritorio}</span></p>','Confirmação de agendamento','EMAIL','T',null,null,null,null); 
